import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectionIntervalRef = useRef(null);
  const detectionTimeoutRef = useRef(null);
  const progressIntervalRef = useRef(null);
  const canvasRef = useRef(document.createElement('canvas'));

  // ============ STATE ============
  const [cameraActive, setCameraActive] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [enrollmentPhoto, setEnrollmentPhoto] = useState(null);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [cameraPermission, setCameraPermission] = useState(null);
  const [videoReady, setVideoReady] = useState(false);

  // ============ VÉRIFIER PERMISSIONS ============
  useEffect(() => {
    if (navigator.permissions && navigator.permissions.query) {
      navigator.permissions.query({ name: 'camera' }).then(result => {
        setCameraPermission(result.state);
        result.onchange = () => setCameraPermission(result.state);
      }).catch(err => console.warn('Permissions API error:', err));
    }
  }, []);

  // ============ ARRÊTER CAMÉRA (Méthode propre) ============
  const stopCamera = useCallback(() => {
    if (detectionIntervalRef.current) clearInterval(detectionIntervalRef.current);
    if (detectionTimeoutRef.current) clearTimeout(detectionTimeoutRef.current);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setCameraActive(false);
    setDetecting(false);
    setVideoReady(false);
  }, []);

  // ============ DÉMARRAGE CAMÉRA ============
  const startCamera = async () => {
    try {
      setError(null);
      stopCamera(); // Reset avant de démarrer

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: 1280, height: 720 },
        audio: false
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setCameraActive(true);
      }
    } catch (err) {
      const msg = err.name === 'NotAllowedError' ? 'Accès refusé' : 'Erreur caméra';
      setError(msg);
      addNotification?.(msg, 'error');
    }
  };

  // ============ LOGIQUE DE CAPTURE CANVAS ============
  const getFrameBase64 = useCallback((quality = 0.8) => {
    if (!videoRef.current || !videoReady) return null;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    // Miroir inverse pour que la capture corresponde à la vue utilisateur
    ctx.translate(canvas.width, 0);
    ctx.scale(-1, 1);
    ctx.drawImage(video, 0, 0);
    return canvas.toDataURL('image/jpeg', quality);
  }, [videoReady]);

  // ============ TRAITER SUCCÈS DÉTECTION ============
  const handleDetectionSuccess = async (matchData, photoCapturée) => {
    setCapturedPhoto(photoCapturée);
    setDetecting(false);

    // On met à jour les infos de base
    setMatchResult({
      name: matchData.student,
      email: matchData.email || 'N/A',
      confidence: (matchData.confidence * 100).toFixed(1),
      attendanceId: matchData.attendance_id,
      timestamp: new Date().toLocaleTimeString('fr-FR')
    });

    // Tentative de récupération de la photo d'enrôlement via l'ID étudiant
    try {
        if (matchData.student_id) {
            const studentInfo = await studentsAPI.getById(matchData.student_id);
            if (studentInfo?.data?.photo_url) {
                setEnrollmentPhoto(studentInfo.data.photo_url);
            }
        }
    } catch (err) {
        console.warn("Impossible de charger la photo d'enrôlement");
    }

    addNotification?.(`✅ ${matchData.student} reconnu`, 'success');
  };

  // ============ LANCER DÉTECTION 10 SECONDES ============
  const startDetection = () => {
    if (!cameraActive || !videoReady) return;

    setDetecting(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setEnrollmentPhoto(null);
    setError(null);

    let bestMatch = null;
    const startTime = Date.now();
    const DURATION = 10000;

    // Intervalle de reconnaissance (toutes les 600ms pour ne pas surcharger le serveur)
    detectionIntervalRef.current = setInterval(async () => {
      const frame = getFrameBase64(0.7);
      if (!frame) return;

      try {
        const response = await attendanceAPI.recognize(frame);
        const data = response?.data;
        if (data?.success && data?.confidence > 0.4) {
          if (!bestMatch || data.confidence > bestMatch.confidence) {
            bestMatch = { ...data, capturedFrame: frame };
          }
        }
      } catch (e) { console.error("Reconnaissance failed", e); }
    }, 600);

    // Barre de progression
    progressIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(100, (elapsed / DURATION) * 100);
      setDetectionProgress(progress);
    }, 100);

    // Fin du temps
    detectionTimeoutRef.current = setTimeout(() => {
      clearInterval(detectionIntervalRef.current);
      clearInterval(progressIntervalRef.current);

      if (bestMatch) {
        handleDetectionSuccess(bestMatch, bestMatch.capturedFrame);
      } else {
        setDetecting(false);
        setError("Aucun visage identifié en 10s");
        addNotification?.("Échec de l'identification", "error");
      }
    }, DURATION);
  };

  const captureOnce = async () => {
    const frame = getFrameBase64(0.9);
    if (!frame) return;
    setDetecting(true);
    setError(null);

    try {
      const response = await attendanceAPI.recognize(frame);
      if (response?.data?.success) {
        handleDetectionSuccess(response.data, frame);
      } else {
        setError(response?.data?.message || "Non reconnu");
        setDetecting(false);
      }
    } catch (err) {
      setError("Erreur serveur");
      setDetecting(false);
    }
  };

  const resetDetection = () => {
    setMatchResult(null);
    setCapturedPhoto(null);
    setEnrollmentPhoto(null);
    setError(null);
    setDetectionProgress(0);
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>
        <p style={styles.subtitle}>
          {!cameraActive ? 'Activez la caméra pour commencer' : 'Positionnez-vous face à l\'objectif'}
        </p>
      </div>

      {cameraActive ? (
        <div style={styles.videoSection}>
          <div style={styles.videoContainer}>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              onLoadedMetadata={() => setVideoReady(true)}
              style={styles.video}
            />
            <div style={{
              ...styles.statusBadge,
              background: detecting ? COLORS.primary : COLORS.success
            }}>
              {detecting ? '🔄 ANALYSE EN COURS...' : '✅ CAMÉRA ACTIVE'}
            </div>

            {detecting && (
              <div style={styles.timerBadge}>
                ⏱️ {((100 - detectionProgress) / 10).toFixed(1)}s restantes
              </div>
            )}
          </div>

          <div style={styles.progressBar}>
            <div style={{ ...styles.progressFill, width: `${detectionProgress}%` }} />
          </div>
        </div>
      ) : (
        <div style={styles.cameraOffBox} onClick={startCamera}>
          <p style={styles.cameraOffText}>📹 Caméra désactivée</p>
          <button style={{...styles.btn, background: COLORS.primary, marginTop: 15}}>Allumer</button>
        </div>
      )}

      <div style={styles.actions}>
        {cameraActive && (
          <>
            <button 
                onClick={captureOnce} 
                disabled={detecting} 
                style={{ ...styles.btn, background: COLORS.primary, opacity: detecting ? 0.5 : 1 }}
            >
              📸 Capture Instantanée
            </button>
            <button 
                onClick={startDetection} 
                disabled={detecting} 
                style={{ ...styles.btn, background: COLORS.warning, opacity: detecting ? 0.5 : 1 }}
            >
              🔍 Scan 10 secondes
            </button>
            <button onClick={stopCamera} style={{ ...styles.btn, background: COLORS.danger }}>
              🛑 Arrêter
            </button>
          </>
        )}
      </div>

      {error && <div style={styles.errorBox}>{error}</div>}

      {matchResult && (
        <div style={styles.resultSection}>
          <h2 style={styles.resultTitle}>✅ Étudiant Identifié</h2>

          <div style={styles.imagesGrid}>
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>Référence (Enrôlement)</h3>
              <div style={styles.imagePlaceholder}>
                {enrollmentPhoto ? <img src={enrollmentPhoto} style={styles.image} alt="Ref" /> : <span style={styles.imagePlaceholderText}>Aucune photo <br/> de profil</span>}
              </div>
            </div>
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>Capture Directe</h3>
              <div style={styles.imagePlaceholder}>
                <img src={capturedPhoto} style={styles.image} alt="Capture" />
              </div>
            </div>
          </div>

          <div style={styles.infoBox}>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Nom :</span><span>{matchResult.name}</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Confiance :</span><span style={{color: COLORS.success, fontWeight: 'bold'}}>{matchResult.confidence}%</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>Heure :</span><span>{matchResult.timestamp}</span></div>
          </div>

          <button onClick={resetDetection} style={{ ...styles.btn, background: COLORS.primary, width: '100%' }}>
            🔄 Recommencer
          </button>
        </div>
      )}
    </div>
  );
};

